    configFile = file("../style/google_checks.xml")
    maxWarnings = 0
}

// JaCoCo configuration
jacoco {
    toolVersion = "0.8.11"
}

tasks.jacocoTestReport {
    dependsOn(tasks.test) // Run tests before generating report

    reports {
        xml.required.set(true)   // For CI/CD tools like GitHub Actions
        html.required.set(true)  // For human reading
        csv.required.set(true)   // For badge generators and simple parsers
    }
}

// Optional: Coverage verification rules (NOT failing build)
tasks.jacocoTestCoverageVerification {
    violationRules {
        rule {
            limit {
                minimum = 0.20.toBigDecimal()  // Start with current 20% as baseline
            }
        }
    }
}

// JAR configuration
tasks.jar {
    manifest {
        attributes["Main-Class"] = "main.Main"
    }
}

// Shadow JAR configuration
tasks.shadowJar {
    archiveClassifier.set("")
    archiveBaseName.set("boomslang")
    archiveVersion.set("")
    manifest {
        attributes["Main-Class"] = "main.Main"
    }
    mergeServiceFiles()
}

