    archiveVersion.set("")
    manifest {
        attributes["Main-Class"] = "main.Main"
    }
    configurations = listOf(project.configurations.runtimeClasspath.get())
}

// Build configuration
tasks.build {
    dependsOn(tasks.named("shadowJar"), tasks.named("shadowJarA"))
}

