// Test configuration
tasks.test {
    useTestNG {
        // Prints TestNG's default footer summary
        useDefaultListeners = true
    }
    jvmArgs = listOf(
        "-Djava.library.path=/usr/local/lib",
        "-Dlog4j.configurationFile=../log4j2.xml",
        "-Xmx10g",
        "-Xms10g"
    )

    // Generate JaCoCo coverage report after tests
    finalizedBy(tasks.jacocoTestReport)
    
    testLogging {
        events("started", "passed", "skipped", "failed")
        showStandardStreams = true
        exceptionFormat = org.gradle.api.tasks.testing.logging.TestExceptionFormat.FULL
        showExceptions = true
        showCauses = true
        showStackTraces = true
    }

    // One clean summary at the very end of the whole run
    afterSuite(KotlinClosure2<TestDescriptor, TestResult, Unit>({ desc, result ->
        if (desc.parent == null) { // root suite
            println("\n===== TEST SUMMARY =====")
            println("Total:   ${result.testCount}")
            println("Passed:  ${result.successfulTestCount}")
            println("Failed:  ${result.failedTestCount}")
            println("Skipped: ${result.skippedTestCount}")
            val pct = if (result.testCount > 0) 100.0 * result.successfulTestCount / result.testCount else 0.0
            println("Success rate: %.1f%%".format(pct))
            println("=========================\n")
        }
    }))
}
